export { default as AnchoredToastProvider } from './anchored-toast-provider.svelte';
export type {
  AddAnchoredToastOptions,
  AddToastOptions,
  AddToastVariantOptions,
  AnchoredToastData,
  AnchorPositionerProps,
  ToastActionProps,
  ToastAlign,
  ToastPosition,
  ToastSide,
  ToastType
} from './toast-manager.svelte';
export { anchoredToastManager, toastManager } from './toast-manager.svelte';
export { default as ToastProvider } from './toast-provider.svelte';

/**
 * CSS selectors used to identify focusable elements within a toast.
 * Used for managing keyboard focus when interacting with toasts containing actions.
 */
export const FOCUSABLE_SELECTORS = [
  'button:not([disabled])',
  'input:not([disabled])',
  'textarea:not([disabled])',
  'select:not([disabled])',
  'a[href]',
  '[tabindex]:not([tabindex="-1"])'
].join(', ');

/**
 * Returns true when the element currently matches `:focus-visible`, i.e. focus
 * was acquired via keyboard or another mechanism the user agent considers
 * keyboard-equivalent. Used to gate behaviors (such as pausing toast timers)
 * that should only respond to keyboard focus, not mouse-induced focus.
 */
export const isFocusVisible = (el: Element | null | undefined): boolean => {
  if (!el || typeof (el as HTMLElement).matches !== 'function') return false;
  try {
    return (el as HTMLElement).matches(':focus-visible');
  } catch {
    return false;
  }
};

/**
 * Module-level focus bookkeeping shared by the toaster. Tracks the element
 * that held focus before the user jumped into the toast region (via `F6`),
 * so that leaving the region (via `Tab` past a focus guard or by dismissing
 * the focused toast) can restore focus to where the user was before.
 *
 * Only one toaster instance is active at a time (see `toasterInstanceManager`),
 * which is why a module-level singleton is acceptable here.
 */
let prevFocusElement: HTMLElement | null = null;
let toastRegionClaimed = false;

export const focusManager = {
  getPrevFocus(): HTMLElement | null {
    return prevFocusElement;
  },
  isClaimed(): boolean {
    return toastRegionClaimed;
  },
  releaseClaim(): void {
    toastRegionClaimed = false;
    prevFocusElement = null;
  },
  restoreFocusToPrevElement(): void {
    toastRegionClaimed = false;
    const target = prevFocusElement;
    prevFocusElement = null;
    if (target && typeof document !== 'undefined' && document.contains(target)) {
      try {
        target.focus({ preventScroll: true });
      } catch {
        target.focus();
      }
    }
  },
  savePrevFocus(): void {
    if (typeof document === 'undefined') return;
    const active = document.activeElement;
    if (active instanceof HTMLElement && active !== document.body) {
      prevFocusElement = active;
    } else {
      prevFocusElement = null;
    }
    toastRegionClaimed = true;
  }
};

/**
 * Global configuration constants for toast animations and stacking behavior.
 * These values control timing, spacing, scaling, and easing of toast transitions.
 */
export const ANIMATION_CONFIG = {
  /** Default cubic-bezier easing function for animations. */
  EASING_DEFAULT: 'var(--ease-vs-toast)',
  /** Easing function for exit animations. */
  EASING_EXIT: 'var(--ease-vs-toast)',
  /** Duration of the entry animation in seconds. */
  ENTER_DURATION: 0.75,
  /** Duration of the exit animation in seconds. */
  EXIT_DURATION: 0.75,
  /** Vertical gap (in pixels) between toasts in expanded (hover) state. */
  EXPANDED_GAP: 12,
  /** Maximum number of toasts visible in the stack at once. */
  MAX_VISIBLE_TOASTS: 3,
  /** Minimum scale value for the furthest toast in the stack. */
  MIN_SCALE: 0.92,
  /** Scale reduction factor for each subsequent toast in the stack. */
  SCALE_FACTOR: 0.04,
  /** Duration of the stack reorganization animation in seconds. */
  STACK_DURATION: 0.75,
  /** Vertical offset (in pixels) between stacked toasts in collapsed state. */
  STACK_OFFSET: 16,
  /** Base z-index for the toast layer. */
  Z_INDEX_BASE: 50
} as const;

/**
 * Configuration for initial animation states based on toast position.
 * Defines the starting transform values (x, y) for entering and exiting toasts.
 */
export const POSITION_CONFIGS = {
  'bottom-center': {
    animateIn: { x: 0, y: 100 },
    animateOut: { x: 0, y: 100 }
  },
  'bottom-left': {
    animateIn: { x: 0, y: 100 },
    animateOut: { x: 0, y: 100 }
  },
  'bottom-right': {
    animateIn: { x: 0, y: 100 },
    animateOut: { x: 0, y: 100 }
  },
  'top-center': {
    animateIn: { x: 0, y: -100 },
    animateOut: { x: 0, y: -100 }
  },
  'top-left': {
    animateIn: { x: 0, y: -100 },
    animateOut: { x: 0, y: -100 }
  },
  'top-right': {
    animateIn: { x: 0, y: -100 },
    animateOut: { x: 0, y: -100 }
  }
} as const;

/**
 * Available positions for the toaster on the screen.
 */
export type ToastPosition =
  | 'top-left'
  | 'top-center'
  | 'top-right'
  | 'bottom-left'
  | 'bottom-center'
  | 'bottom-right';

import type { ToastPosition } from './positions';

/** Directions in which a toast can be swiped to dismiss. */
export type SwipeDirection = 'top' | 'bottom' | 'left' | 'right';
/** Axes along which swipe gestures are tracked. */
export type SwipeAxis = 'x' | 'y';

/** Minimum pixel distance required to trigger a swipe dismissal. */
export const SWIPE_DISMISS_THRESHOLD = 45;
/** Minimum velocity (pixels/ms) required to trigger a swipe dismissal. */
export const SWIPE_DISMISS_VELOCITY = 0.11;
/** Distance in pixels to move the toast during the exit animation after a swipe. */
export const SWIPE_EXIT_DISTANCE = 600;
/**
 * Distance the pointer must travel back from the furthest swipe position before
 * the in-progress swipe is treated as cancelled (a "change of mind"). Once
 * cancelled, releasing the pointer snaps the toast back instead of dismissing it.
 */
export const SWIPE_REVERSE_CANCEL_THRESHOLD = 10;

/**
 * Determines the allowed swipe directions based on the toast's position.
 * For example, a "top-right" toast can be swiped "top" or "right".
 *
 * @param position - The toast's position on screen.
 * @returns An array of allowed swipe directions.
 */
export const getDefaultSwipeDirections = (position?: ToastPosition | null): SwipeDirection[] => {
  if (!position) {
    return ['top', 'bottom', 'left', 'right'];
  }

  const [vertical, horizontal] = position.split('-') as [string, string | undefined];
  const directions: SwipeDirection[] = [];

  if (vertical === 'top' || vertical === 'bottom') {
    directions.push(vertical);
  }

  if (horizontal === 'left' || horizontal === 'right') {
    directions.push(horizontal);
  }

  if (directions.length === 0) {
    directions.push('top', 'bottom');
  }

  return directions;
};

import type { Component } from 'svelte';
import { toastState } from './toast-state';
import type {
  PromiseToastState,
  ToastData,
  ToastInput,
  ToastInvoker,
  ToastPromiseOptions,
  ToastVariantInput
} from './types';

/**
 * Helper to normalize string input into a ToastData object.
 */
const normalizeToastData = (data: ToastInput | string): ToastInput => {
  if (typeof data === 'string') {
    return { description: data };
  }
  return data;
};

/**
 * Resolves the state of a promise-based toast (success or error) into actual toast data.
 */
const resolvePromiseState = async <Value>(
  value: Value,
  state: PromiseToastState<Value>
): Promise<Omit<ToastData, 'id'>> => {
  const resolvedValue = typeof state === 'function' ? await state(value) : await state;
  return normalizeToastData(resolvedValue);
};

const getPromiseFallbackDescription = (error: unknown): string => {
  if (error instanceof Error) {
    return error.message;
  }
  if (typeof error === 'string') {
    return error;
  }
  return 'An unknown error occurred while updating the notification.';
};

/**
 * The main entry point for creating toasts.
 * @param data - Toast configuration object or description string.
 * @returns The ID of the created toast.
 */
const createToast: ToastInvoker = ((data: ToastInput | string) => {
  return toastState.add(normalizeToastData(data));
}) as ToastInvoker;

/**
 * Creates a success variant toast.
 */
createToast.success = (data: ToastVariantInput | string): string => {
  if (typeof data === 'string') {
    return toastState.add({ description: data, variant: 'success' });
  }
  return toastState.add({ ...data, variant: 'success' });
};

/**
 * Creates a warning variant toast.
 */
createToast.warning = (data: ToastVariantInput | string): string => {
  if (typeof data === 'string') {
    return toastState.add({ description: data, variant: 'warning' });
  }
  return toastState.add({ ...data, variant: 'warning' });
};

/**
 * Creates an info variant toast.
 */
createToast.info = (data: ToastVariantInput | string): string => {
  if (typeof data === 'string') {
    return toastState.add({ description: data, variant: 'info' });
  }
  return toastState.add({ ...data, variant: 'info' });
};

/**
 * Creates an error (destructive) variant toast.
 */
createToast.error = (data: ToastVariantInput | string): string => {
  if (typeof data === 'string') {
    return toastState.add({ description: data, variant: 'destructive' });
  }
  return toastState.add({ ...data, variant: 'destructive' });
};

/**
 * Creates a custom component toast.
 * @param component - The Svelte component to render.
 * @param options - Additional options and props for the component.
 */
createToast.custom = (
  component, // Type inferred from ToastInvoker
  options
): string => {
  return toastState.add({
    ...(options ?? {}),
    component: component as Component<any>,
    variant: 'custom'
  });
};

/**
 * Creates a toast that tracks a promise's lifecycle.
 * Updates automatically from loading -> success/error.
 *
 * @param promise - The promise to observe.
 * @param options - Configuration for loading, success, and error states.
 * @returns A promise that resolves with the original value or rejects with
 *          the original error, so callers can `await` the underlying work.
 */
createToast.promise = <T, E = unknown>(
  promise: PromiseLike<T>,
  options: ToastPromiseOptions<T, E>
): Promise<T> => {
  const loadingData = normalizeToastData(options.loading);
  const toastId = toastState.add({
    ...loadingData,
    duration: loadingData.duration ?? 0,
    isLoading: true,
    showClose: loadingData.showClose ?? true
  });

  const handleResult = async <Value>(
    state: PromiseToastState<Value>,
    value: Value,
    defaultVariant?: ToastData['variant']
  ) => {
    const payload = await resolvePromiseState(value, state);
    toastState.update(toastId, {
      ...payload,
      duration: payload.duration,
      isLoading: false,
      showClose: payload.showClose ?? true,
      variant: payload.variant ?? defaultVariant
    });
  };

  const applyPromiseFallback = (error: unknown) => {
    toastState.update(toastId, {
      description: getPromiseFallbackDescription(error),
      duration: 5000,
      isLoading: false,
      showClose: true,
      title: 'Operation failed',
      variant: 'destructive'
    });
  };

  const source = Promise.resolve(promise);

  void source
    .then((value) => handleResult(options.success, value, 'success'))
    .catch((error: E) => handleResult(options.error, error, 'destructive'))
    .catch((error) => {
      applyPromiseFallback(error);
    });

  return source;
};

/**
 * Updates an existing toast in place.
 * Accepts a string (shorthand for `{ description }`) or a partial data object.
 */
createToast.update = (id: string, data: Partial<Omit<ToastData, 'id'>> | string): void => {
  const payload = typeof data === 'string' ? { description: data } : data;
  toastState.update(id, payload);
};

/**
 * Dismisses a toast by ID.
 */
createToast.dismiss = (id: string): void => {
  toastState.update(id, { shouldClose: true });
};

/**
 * Dismisses all active toasts.
 */
createToast.dismissAll = (): void => {
  toastState.dismissAll();
};

export const toast = createToast;

import type { ToastData, ToastSubscriber } from './types';

/**
 * Manages the global state of toast notifications.
 * Implements a singleton pattern with a subscription mechanism.
 */
class ToastState {
  private toasts: ToastData[] = [];
  private subscribers: Set<ToastSubscriber> = new Set();
  private idCounter = 0;

  /**
   * Subscribes to changes in the toast list.
   * @param callback - Function to be called when the toast list updates.
   * @returns A cleanup function to unsubscribe.
   */
  subscribe(callback: ToastSubscriber): () => void {
    this.subscribers.add(callback);
    return () => {
      this.subscribers.delete(callback);
    };
  }

  private notify(): void {
    this.subscribers.forEach((callback) => {
      callback([...this.toasts]);
    });
  }

  private generateId(): string {
    return `toast-${Date.now()}-${++this.idCounter}`;
  }

  /**
   * Adds a new toast to the state, or updates an existing one in place
   * when `data.id` matches a toast that is still active.
   * @param data - The toast configuration. If `id` is provided and refers
   *   to an active toast, the call performs an upsert and returns that id.
   * @returns The id of the created or updated toast.
   */
  add(data: Omit<ToastData, 'id'> & { id?: string }): string {
    const requestedId = data.id;
    let generation = 0;
    if (requestedId) {
      const existing = this.toasts.find((t) => t.id === requestedId);
      if (existing && !existing.shouldClose && !existing.isLeaving) {
        // Toast is already active — pulse it in place instead of replacing.
        this.update(requestedId, { bubbleKey: (existing.bubbleKey ?? 0) + 1 });
        return requestedId;
      }
      // Toast is leaving or gone — remove stale entry and recreate fresh.
      generation = (existing?.generation ?? 0) + 1;
      this.toasts = this.toasts.filter((t) => t.id !== requestedId);
    }

    const id = requestedId ?? this.generateId();
    const { id: _ignored, ...rest } = data;
    void _ignored;
    const newToast: ToastData = { ...rest, generation, id };
    this.toasts = [newToast, ...this.toasts];
    this.notify();
    return id;
  }

  /**
   * Removes a toast from the state by its ID.
   * @param id - The ID of the toast to remove.
   */
  remove(id: string): void {
    this.toasts = this.toasts.filter((toast) => toast.id !== id);
    this.notify();
  }

  /**
   * Updates an existing toast's data.
   * @param id - The ID of the toast to update.
   * @param data - Partial data to merge into the existing toast.
   */
  update(id: string, data: Partial<ToastData>): void {
    this.toasts = this.toasts.map((toast) => (toast.id === id ? { ...toast, ...data } : toast));
    this.notify();
  }

  /**
   * Marks all active toasts for dismissal.
   * Triggers the closing animation by setting `shouldClose` to true.
   */
  dismissAll(): void {
    this.toasts = this.toasts.map((toast) => ({
      ...toast,
      duration: 0,
      shouldClose: true
    }));
    this.notify();
  }

  /**
   * Returns the current list of active toasts.
   * @returns A copy of the toast array.
   */
  getToasts(): ToastData[] {
    return [...this.toasts];
  }
}

/** Global singleton instance of the toast state. */
export const toastState = new ToastState();
export { ToastState };

/**
 * Manages unique instances of the Toaster component to prevent conflicts.
 * Ensures that if multiple Toasters are rendered, only one (the first or primary) is active.
 */
class ToasterInstanceManager {
  private activeInstanceId: string | null = null;
  private instanceCounter = 0;
  private instanceIds: string[] = [];

  /**
   * Registers a new toaster instance.
   * @returns A unique instance ID.
   */
  registerInstance(): string {
    const instanceId = `toaster-${++this.instanceCounter}`;
    this.instanceIds.push(instanceId);
    if (!this.activeInstanceId || !this.instanceIds.includes(this.activeInstanceId)) {
      this.activeInstanceId = instanceId;
    }
    return instanceId;
  }

  /**
   * Unregisters an instance, potentially freeing up the active slot.
   * @param instanceId - The ID of the instance to unregister.
   */
  unregisterInstance(instanceId: string): void {
    this.instanceIds = this.instanceIds.filter((id) => id !== instanceId);
    if (this.activeInstanceId === instanceId) {
      this.activeInstanceId = this.instanceIds[0] ?? null;
    } else if (this.activeInstanceId && !this.instanceIds.includes(this.activeInstanceId)) {
      this.activeInstanceId = this.instanceIds[0] ?? null;
    }
  }

  /**
   * Checks if the given instance is the currently active one.
   * @param instanceId - The ID to check.
   * @returns True if active, false otherwise.
   */
  isActiveInstance(instanceId: string): boolean {
    return this.activeInstanceId === instanceId;
  }
}

export const toasterInstanceManager = new ToasterInstanceManager();
export { ToasterInstanceManager };

import type { Component } from 'svelte'; // Use Component
import type { VariantProps } from 'tailwind-variants';
import type { ToastPosition } from './positions';
import type { SwipeAxis, SwipeDirection } from './swipe';
import type { toastContainerVariants } from './variants';

/**
 * Represents the data structure for a single toast notification.
 */
export interface ToastData extends VariantProps<typeof toastContainerVariants> {
  /** Optional action button to display within the toast. */
  action?: {
    /** Label for the action button. */
    label: string;
    /** Callback function executed when the action button is clicked. */
    onClick: () => void;
  };
  /** Incremented each time a duplicate-id add is called on an active toast, triggering a bubble animation. */
  bubbleKey?: number;
  /** Optional CSS class to apply to the toast container. */
  className?: string;
  /** Custom Svelte component to render instead of the default toast layout. */
  component?: Component<any>; // Use Component<any> for storage
  /** Props to pass to the custom component. */
  componentProps?: Record<string, any>;
  /** Additional details or description displayed below the title. */
  description?: string;
  /**
   * Duration in milliseconds before the toast automatically closes.
   * Defaults to 5000ms. Set to `0` or `Infinity` to keep open indefinitely.
   */
  duration?: number;
  /** Incremented each time the toast is reset with the same id, forcing DOM recreation. */
  generation?: number;
  /** Unique identifier for the toast. */
  id: string;
  /** Internal flag: signals that the toast is currently leaving the DOM. */
  isLeaving?: boolean;
  /** Whether the toast is in a loading state. */
  isLoading?: boolean;
  /** Callback fired when the toast finishes its auto-close timer. */
  onAutoClose?: () => void;
  /** Callback fired when the toast is dismissed manually (button, swipe, `toast.dismiss`, etc.). */
  onDismiss?: () => void;
  /** The position on the screen where this toast should appear. */
  position?: ToastPosition;
  /**
   * Announcement priority for assistive technology.
   * - `"low"` (default) renders the toast as a `dialog` (or `alertdialog` for
   *   the destructive variant) and relies on the existing `aria-live` region
   *   for announcements.
   * - `"high"` additionally mounts a visually-hidden `role="alert"` mirror
   *   alongside the toast, so screen readers announce the message
   *   immediately even while the main toast has not received focus.
   */
  priority?: 'low' | 'high';
  /** Internal flag: signals that the toast should begin its closing animation. */
  shouldClose?: boolean;
  /** Whether to show the close button. Defaults to `true`. */
  showClose?: boolean;
  /** The main title of the toast notification. */
  title?: string;
}

/**
 * Represents the possible states for a promise-based toast.
 * Can be a static message string, a ToastData object (minus ID), or a function returning one of those.
 */
export type PromiseToastState<Value> =
  | string
  | Omit<ToastData, 'id'>
  | ((
      value: Value
    ) => string | Omit<ToastData, 'id'> | PromiseLike<string | Omit<ToastData, 'id'>>);

/**
 * Options for the `toast.promise` function.
 */
export type ToastPromiseOptions<SuccessValue = unknown, ErrorValue = unknown> = {
  /** The message or data to show while the promise is pending. */
  loading: Omit<ToastData, 'id'> | string;
  /** The message or data to show when the promise resolves successfully. */
  success: PromiseToastState<SuccessValue>;
  /** The message or data to show when the promise rejects. */
  error: PromiseToastState<ErrorValue>;
};

/**
 * The interface for the main `toast` function and its utility methods.
 */
/**
 * Optional shape passed to the `toast()` invoker. `id` is optional and,
 * when provided, makes the call upsert the matching toast in place
 * instead of creating a new one.
 */
export type ToastInput = Omit<ToastData, 'id'> & { id?: string };
/** Same as {@link ToastInput} for variant helpers — `variant` is fixed by the helper. */
export type ToastVariantInput = Omit<ToastData, 'id' | 'variant'> & { id?: string };

export type ToastInvoker = {
  /**
   * Creates a default toast notification, or updates an existing one when
   * `data.id` matches an active toast.
   * @param data - The toast options or description string.
   * @returns The ID of the created or updated toast.
   */
  (data: ToastInput | string): string;
  /**
   * Creates a success toast notification.
   */
  success: (data: ToastVariantInput | string) => string;
  /**
   * Creates a warning toast notification.
   */
  warning: (data: ToastVariantInput | string) => string;
  /**
   * Creates an info toast notification.
   */
  info: (data: ToastVariantInput | string) => string;
  /**
   * Creates an error toast notification.
   */
  error: (data: ToastVariantInput | string) => string;
  /**
   * Creates a custom component toast.
   * @param component - The Svelte component to render.
   * @param options - Additional options and props for the component.
   */
  custom: <Props extends Record<string, any> = Record<string, any>>(
    component: Component<Props>,
    options?: Omit<ToastData, 'id' | 'component' | 'variant' | 'componentProps'> & {
      id?: string;
      componentProps?: Omit<Props, 'id' | 'toast'>;
    }
  ) => string;
  /**
   * Creates a toast that updates based on the state of a Promise.
   * @param promise - The promise to track.
   * @param options - Configuration for loading, success, and error states.
   * @returns A promise that resolves with the original value or rejects with
   *          the original error, so callers can `await` the underlying work.
   */
  promise: <T, E = unknown>(
    promise: PromiseLike<T>,
    options: ToastPromiseOptions<T, E>
  ) => Promise<T>;
  /**
   * Updates an existing toast in place. Useful for streaming progress
   * messages or replacing a loading toast without flicker.
   * @param id - The ID returned when the toast was created.
   * @param data - Partial data to merge into the existing toast. Pass a
   *   string as shorthand for `{ description }`.
   */
  update: (id: string, data: Partial<Omit<ToastData, 'id'>> | string) => void;
  /**
   * Dismisses a specific toast by its ID.
   * @param id - The ID of the toast to dismiss.
   */
  dismiss: (id: string) => void;
  /**
   * Dismisses all currently active toasts.
   */
  dismissAll: () => void;
};

/**
 * Extends `ToastData` with positioning information for rendering.
 */
export type PositionedToast = ToastData & {
  /** The visual index of the toast in the stack. */
  index: number;
  /** The render order index (z-index calculation base). */
  renderIndex: number;
  /** Total number of toasts in the current group. */
  total: number;
};

/**
 * Context provided to toast items (mostly for internal use).
 */
export interface VarselItemContext {
  collapsedOffset?: number;
  expandedGap?: number;
  expandedOffset?: number;
  hiddenCollapsedOffset?: number;
  isGroupHovered?: boolean;
  onGroupHoverEnter?: () => void;
  onHeightChange?: (id: string, height: number) => void;
  onRemove: (id: string) => void;
  toast: PositionedToast;
}

/** Function signature for toast state subscribers. */
export type ToastSubscriber = (toasts: ToastData[]) => void;

export type { SwipeAxis, SwipeDirection, ToastPosition };

import { tv } from 'tailwind-variants';

export const toastContainerVariants = tv({
  base: 'pointer-events-auto fixed will-change-transform',
  defaultVariants: {
    position: 'bottom-center',
    variant: 'default'
  },
  variants: {
    position: {
      'bottom-center': 'bottom-4 left-1/2 w-full max-w-sm -translate-x-1/2 transform',
      'bottom-left': 'bottom-4 left-4 w-full max-w-sm',
      'bottom-right': 'right-4 bottom-4 w-full max-w-sm',
      'top-center': 'top-4 left-1/2 w-full max-w-sm -translate-x-1/2 transform',
      'top-left': 'top-4 left-4 w-full max-w-sm',
      'top-right': 'top-4 right-4 w-full max-w-sm'
    },
    variant: {
      custom: '',
      default: 'rounded-lg border shadow-lg/5 bg-popover text-popover-foreground',
      destructive: 'rounded-lg border shadow-lg/5 bg-popover text-destructive',
      info: 'rounded-lg border shadow-lg/5 bg-popover text-info',
      success: 'rounded-lg border shadow-lg/5 bg-popover text-success',
      warning: 'rounded-lg border shadow-lg/5 bg-popover text-warning'
    }
  }
