/* Spinner Styles */
.vs-spinner {
	display: inline-flex;
	width: 1rem;
	height: 1rem;
	align-items: center;
	justify-content: center;
	flex-shrink: 0;
	position: absolute;
	inset: 0;
	transform-origin: center;
}

.vs-spinner--active {
	opacity: 1;
}

.vs-spinner--finish {
	animation: vs-spinner-finish 0.42s var(--ease-vs-toast) forwards;
}

.vs-spinner svg {
	width: 100%;
	height: 100%;
	animation: vs-spin 1s linear infinite;
}

/* Icon Styles */
.vs-icon {
	display: inline-flex;
	width: 1rem;
	height: 1rem;
	align-items: center;
	justify-content: center;
	flex-shrink: 0;
	position: absolute;
	inset: 0;
}

.vs-icon--static {
	opacity: 1;
	transform: scale(1);
}

.vs-icon--waiting {
	opacity: 0;
	transform: scale(0.25);
	filter: blur(4px);
}

.vs-icon--pop {
	animation: vs-icon-pop 0.36s var(--ease-vs-pop) forwards;
}

.vs-icon svg {
	width: 100%;
	height: 100%;
}

.vs-sr-only {
	position: absolute;
	width: 1px;
	height: 1px;
	padding: 0;
	margin: -1px;
	overflow: hidden;
	clip: rect(0, 0, 0, 0);
	white-space: nowrap;
	border: 0;
}

/* Bubble pulse applied to an active toast when re-triggered with the same id */
.vs-bubble {
	animation: vs-bubble 0.32s cubic-bezier(0.5, 1, 0.89, 1);
}

@keyframes vs-bubble {
	0% {

		scale: 1;
	}

	30% {
		scale: 1.025;
	}

	60% {
		scale: 0.99;
	}

	100% {
		scale: 1;
	}

}

@keyframes vs-spin {
	to {
		transform: rotate(360deg);
	}
}

@keyframes vs-spinner-finish {
	0% {
		opacity: 1;
		transform: scale(1);
		filter: blur(0);
	}

	100% {
		opacity: 0;
		transform: scale(0.25);
		filter: blur(4px);
	}
}

@keyframes vs-icon-pop {
	0% {
		opacity: 0;
		transform: scale(0.25);
		filter: blur(4px);
	}

	100% {
		opacity: 1;
		transform: scale(1);
		filter: blur(0);
	}
}

@media (prefers-reduced-motion: reduce) {
	.vs-spinner svg {
		animation-duration: 2s;
	}

	.vs-spinner--finish {
		animation-duration: 0s;
	}

	.vs-icon--pop {
		animation: none;
		opacity: 1;
		transform: scale(1);
	}

	.vs-bubble {
		animation: none;
	}
}

